from pathlib import Path
p = Path('README.md')
s = p.read_text()
s = s.replace('Quick boundary tests normally run for **1 minute**. Long validation tests run for **1 hour**.', 'Quick boundary tests normally run for **1 minute**. Long validation tests run for **1 hour**. The dynamic Low VMIN floor sweep is measurement-only and does not run a stress test at every frequency.')
s = s.replace('Before **every built-in test**, the Wizard reads Horizon OC\'s live `hoc:clk` context and verifies all three Temporary Overrides:', 'Before **every built-in test and every VMIN floor probe**, the Wizard reads Horizon OC\'s live `hoc:clk` context and verifies all three Temporary Overrides:')
s = s.replace('# New in v0.4.0-beta.4', '# New in v0.4.0-beta.5')
s = s.replace('These shortcuts deliberately bypass the built-in stress test. Use them only for values you already trust from previous testing.', 'These shortcuts deliberately bypass the built-in stress test. Use them only for values you already trust from previous testing.\n\n**Exception:** the dynamic VMIN floor-probe stages are measurements, not PASS/FAIL stability tests. There, `A` performs the required measurement, `+` performs the same measurement for convenience, and `X` is disabled.')
s = s.replace('At each step the Wizard reads the **live CPU rail voltage reported by Horizon OC**. It remembers the highest CPU frequency still operating at the configured VMIN floor (within one 5 mV PMIC step).', 'At each step the Wizard verifies CPU/GPU/RAM overrides and reads the **live CPU rail voltage reported by Horizon OC**. The probe takes **7 context samples** and uses the **median of valid readings** so a single stale HOC poll does not decide the crossover. It remembers the highest CPU frequency still operating at the configured VMIN floor (within one 5 mV PMIC step).\n\nThese sweep points are **measurement-only**. They do not each run another 1-minute stress test. The actual stability confirmation is concentrated at the highest detected floor-bound CPU clock.')
p.write_text(s)
